import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'screen_catalog.dart';

/// `docs/design/review.md` has a gallery that places each Flutter screenshot
/// next to its approved board. It is generated from the screen catalog, so it
/// always links every screenshot: `tool/export_screens.sh` (which runs these
/// tests with `--update-goldens`) rewrites it, and the tests fail when it is
/// out of date.
const _begin =
    '<!-- gallery:begin (generated by app/tool/export_screens.sh) -->';
const _end = '<!-- gallery:end -->';
const languages = ['en', 'am'];

final _review = File('../docs/design/review.md');

String _fileName(DesignScreen s, String lang, String size) =>
    '${s.slug}-$lang-$size.png';

/// "H05-EraSetup" → "H05 · Era setup".
String _boardTitle(String board) {
  final m = RegExp(r'^(H\d+)-(.*)$').firstMatch(board)!;
  final words = m
      .group(2)!
      .replaceAllMapped(RegExp(r'(?<=[a-z])(?=[A-Z])'), (_) => ' ')
      .toLowerCase();
  return '${m.group(1)} · ${words[0].toUpperCase()}${words.substring(1)}';
}

String buildGallery() {
  final groups = <String?, List<DesignScreen>>{};
  for (final s in designScreens) {
    groups.putIfAbsent(s.board, () => []).add(s);
  }
  final boards = groups.keys.whereType<String>().toList()..sort();
  final out = StringBuffer()
    ..writeln(_begin)
    ..writeln();
  final small = designSizes.keys.first;
  final large = designSizes.keys.last;

  for (final board in [...boards, null]) {
    final screens = groups[board];
    if (screens == null) continue;
    if (board == null) {
      out
        ..writeln('### No approved board')
        ..writeln()
        ..writeln(
          'States the boards do not draw. They are specified in '
          '[`screens.md`](screens.md) ("Error and loading patterns" and the '
          'sections of the screens they belong to).',
        );
    } else {
      out
        ..writeln('### ${_boardTitle(board)}')
        ..writeln()
        ..writeln(
          '[Approved board (HTML)](artifacts/$board.dc.html) · English left, '
          'Amharic right:',
        )
        ..writeln()
        ..writeln(
          '<img src="screens/$board.webp" width="420" '
          'alt="Approved board ${_boardTitle(board)}">',
        );
    }
    out
      ..writeln()
      ..writeln('| State | English | Amharic | Larger phone (430×932) |')
      ..writeln('|---|---|---|---|');
    for (final s in screens) {
      final cells = [
        for (final lang in languages)
          '<img src="flutter/${_fileName(s, lang, small)}" width="180" '
              'alt="${s.title}, $lang">',
      ];
      final links = [
        for (final (lang, name) in [('en', 'English'), ('am', 'Amharic')])
          '[$name](flutter/${_fileName(s, lang, large)})',
      ].join(' · ');
      out.writeln(
        '| ${s.title}<br>`${s.slug}` | ${cells.join(' | ')} | $links |',
      );
    }
    out.writeln();
  }
  out.write(_end);
  return out.toString();
}

void main() {
  test('the gallery in review.md is current and links every screenshot', () {
    final doc = _review.readAsStringSync();
    final start = doc.indexOf(_begin);
    final end = doc.indexOf(_end);
    expect(start, isNonNegative, reason: 'review.md lost its gallery markers');
    expect(end, greaterThan(start));
    final current = doc.substring(start, end + _end.length);
    final expected = buildGallery();

    if (autoUpdateGoldenFiles) {
      _review.writeAsStringSync(
        doc.replaceRange(start, end + _end.length, expected),
      );
      return;
    }
    expect(
      current,
      expected,
      reason: 'review.md is out of date: run app/tool/export_screens.sh',
    );
    for (final s in designScreens) {
      for (final lang in languages) {
        for (final size in designSizes.keys) {
          expect(doc, contains('flutter/${_fileName(s, lang, size)}'));
        }
      }
    }
  });

  test('every approved board named exists, as source and as a picture', () {
    final boards = {for (final s in designScreens) ?s.board};
    expect(boards, isNotEmpty);
    for (final b in boards) {
      expect(File('../docs/design/artifacts/$b.dc.html').existsSync(), isTrue);
      expect(File('../docs/design/screens/$b.webp').existsSync(), isTrue);
    }
  });

  test('screen slugs are unique and screenshot names well formed', () {
    final slugs = designScreens.map((s) => s.slug).toList();
    expect(slugs.toSet().length, slugs.length);
    for (final s in slugs) {
      expect(s, matches(RegExp(r'^[a-z0-9]+(-[a-z0-9]+)*$')));
    }
  });

  test('docs/design/flutter holds exactly the screenshots, no stale ones', () {
    if (autoUpdateGoldenFiles) return; // the goldens are being written now
    final expected = {
      for (final s in designScreens)
        for (final lang in languages)
          for (final size in designSizes.keys) _fileName(s, lang, size),
    };
    final found = {
      for (final f in Directory.fromUri(designScreenshotsDir).listSync())
        if (f is File && f.path.endsWith('.png')) f.uri.pathSegments.last,
    };
    expect(found.difference(expected), isEmpty, reason: 'stale screenshots');
    expect(expected.difference(found), isEmpty, reason: 'missing screenshots');
  });
}
